import functools

from flask import Blueprint, flash, g, redirect, render_template_string, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

from db import get_db

bp = Blueprint("auth", __name__)

FORM = """
<h1>{{ title }}</h1>
{% for m in get_flashed_messages() %}<p class="flash">{{ m }}</p>{% endfor %}
<form method="post">
  <label>Username <input name="username" required></label>
  <label>Password <input name="password" type="password" required></label>
  <button>{{ title }}</button>
</form>
"""


@bp.before_app_request
def load_user():
    uid = session.get("user_id")
    g.user = None
    if uid is not None:
        g.user = get_db().execute("SELECT id, username FROM users WHERE id = ?", (uid,)).fetchone()


def login_required(view):
    @functools.wraps(view)
    def wrapped(**kwargs):
        if g.user is None:
            return redirect(url_for("auth.login"))
        return view(**kwargs)
    return wrapped


@bp.route("/signup", methods=("GET", "POST"))
def signup():
    if request.method == "POST":
        username = request.form["username"].strip()
        password = request.form["password"]
        if not username or len(password) < 8:
            flash("Pick a username and a password of at least 8 characters.")
        else:
            db = get_db()
            try:
                db.execute("INSERT INTO users (username, password_hash) VALUES (?, ?)",
                           (username, generate_password_hash(password)))
                db.commit()
            except db.IntegrityError:
                flash(f"{username} is taken.")
            else:
                return redirect(url_for("auth.login"))
    return render_template_string(FORM, title="Sign up")


@bp.route("/login", methods=("GET", "POST"))
def login():
    if request.method == "POST":
        row = get_db().execute("SELECT * FROM users WHERE username = ?",
                               (request.form["username"].strip(),)).fetchone()
        if row is None or not check_password_hash(row["password_hash"], request.form["password"]):
            flash("Wrong username or password.")
        else:
            session.clear()
            session["user_id"] = row["id"]
            return redirect(url_for("notes.index"))
    return render_template_string(FORM, title="Log in")


@bp.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("auth.login"))
```

