from flask import Blueprint, abort, g, redirect, render_template_string, request, url_for

from auth import login_required
from db import get_db

bp = Blueprint("notes", __name__)

PAGE = """
<h1>{{ g.user['username'] }}'s notes</h1>
<p><a href="{{ url_for('auth.logout') }}">Log out</a></p>
<form method="post" action="{{ url_for('notes.add') }}">
  <textarea name="body" required></textarea>
  <button>Add note</button>
</form>
<ul>
{% for n in notes %}
  <li>{{ n['body'] }}
    <form method="post" action="{{ url_for('notes.delete', note_id=n['id']) }}" style="display:inline">
      <button>Delete</button>
    </form>
  </li>
{% else %}
  <li>No notes yet.</li>
{% endfor %}
</ul>
"""


@bp.route("/")
@login_required
def index():
    notes = get_db().execute("SELECT id, body FROM notes WHERE user_id = ? ORDER BY created DESC, id DESC",
                             (g.user["id"],)).fetchall()
    return render_template_string(PAGE, notes=notes)


@bp.route("/notes", methods=("POST",))
@login_required
def add():
    body = request.form.get("body", "").strip()
    if body:
        db = get_db()
        db.execute("INSERT INTO notes (user_id, body) VALUES (?, ?)", (g.user["id"], body))
        db.commit()
    return redirect(url_for("notes.index"))


@bp.route("/notes/<int:note_id>/delete", methods=("POST",))
@login_required
def delete(note_id):
    db = get_db()
    cur = db.execute("DELETE FROM notes WHERE id = ? AND user_id = ?", (note_id, g.user["id"]))
    db.commit()
    if cur.rowcount == 0:
        abort(404)  # not yours, or already gone
    return redirect(url_for("notes.index"))
```

