```python
import pytest

from app import create_app
from db import get_db


@pytest.fixture
def app(tmp_path):
    return create_app({"TESTING": True, "DATABASE": str(tmp_path / "test.sqlite"), "SECRET_KEY": "test"})


@pytest.fixture
def client(app):
    return app.test_client()


def signup(client, username="sam", password="correct horse"):
    return client.post("/signup", data={"username": username, "password": password})


def login(client, username="sam", password="correct horse"):
    return client.post("/login", data={"username": username, "password": password})


def test_signup_then_login(client):
    assert signup(client).headers["Location"].endswith("/login")
    r = login(client)
    assert r.status_code == 302 and r.headers["Location"].endswith("/")
    assert b"sam's notes" in client.get("/").data


def test_password_is_stored_hashed(app, client):
    signup(client)
    with app.app_context():
        stored = get_db().execute("SELECT password_hash FROM users WHERE username = 'sam'").fetchone()[0]
    assert stored != "correct horse" and stored.startswith(("scrypt:", "pbkdf2:"))


def test_wrong_password_is_refused(client):
    signup(client)
    r = login(client, password="wrong password")
    assert r.status_code == 200 and b"Wrong username or password" in r.data


def test_duplicate_username(client):
    signup(client)
    assert b"sam is taken" in signup(client).data


def test_short_password_is_refused(client):
    assert b"at least 8 characters" in signup(client, password="short").data


def test_notes_need_login(client):
    r = client.get("/")
    assert r.status_code == 302 and r.headers["Location"].endswith("/login")


def test_logout(client):
    signup(client)
    login(client)
    client.get("/logout")
    assert client.get("/").status_code == 302
```

**Running it**

```
pip install flask pytest
python app.py          # http://127.0.0.1:5000/signup
pytest                 # from the project folder
```

Notes on the design:

- Passwords are never stored: only the salted hash from `generate_password_hash`, checked with `check_password_hash` at login.
- Deleting a note checks `user_id` in the same `DELETE` statement, so nobody can delete someone else's note by guessing its number; it returns 404 instead.
- The tests use a fresh SQLite file in a temporary folder for each test, so they never touch `notes.sqlite`.
- Change `SECRET_KEY` before you put this anywhere other people can reach it.

